  public static string T(string key){string[] v; return D.TryGetValue(key,out v)?v[AppSession.Persian?0:1]:key;}
  public static void Load(){try{var p=Path.Combine(Application.UserAppDataPath,"language.txt"); if(File.Exists(p)) AppSession.Persian=File.ReadAllText(p).Trim()!="en";}catch{}}
  public static void Set(bool persian){AppSession.Persian=persian; try{Directory.CreateDirectory(Application.UserAppDataPath);File.WriteAllText(Path.Combine(Application.UserAppDataPath,"language.txt"),persian?"fa":"en");}catch{}}
